SELECT (SELECT name FROM warehouses w WHERE w.warehouse_id = s.warehouse_id), SUM(CASE WHEN on_hand_units = 0 THEN 1 ELSE 0 END) * 1.0 / COUNT(*) FROM inventory_snapshots s WHERE s.warehouse_id IN (SELECT warehouse_id FROM warehouses WHERE name LIKE 'Gazipur-%') AND s.snapshot_date >= DATE '2026-01-01' AND s.snapshot_date <= DATE '2026-10-31' GROUP BY s.warehouse_id
